insert into public.data_source_state(source_id) values ('uka-genomstromning-regional') on conflict do nothing;
insert into public.indicators(id,name,description,unit,styrande_kalla,source_table_id,frequency,visibility,is_example)
values
('uka-examensfrekvens','Examensfrekvens på program','Andel programnybörjare med avsedd examen inom nominell studietid plus tre år. Period = nybörjarläsår. Lärosäte: examen vid samma lärosäte; Riket: oavsett lärosäte. Program, kön och ålder bevaras. Korta kompletterande lärarutbildningar exkluderas enligt UKÄ.','procent','UKÄ','135','Årlig','publik',false),
('uka-kvarvaro-program','Kvarvaro termin 3 på program','Andel programnybörjare kvar på samma program termin 3. Lärosäte: samma program och lärosäte; Riket: oavsett lärosäte. Period = nybörjarläsår. Program, kön och ålder bevaras. Frånvaro är inte liktydigt med permanent studieavbrott.','procent','UKÄ','134','Årlig','publik',false),
('uka-kvarvaro-hogskolenyborjare','Kvarvaro termin 3 för högskolenybörjare','Andel högskolenybörjare registrerade på samma lärosäte termin 3, inklusive inresande. Period = nybörjarläsår. Frånvaro får inte tolkas som permanent studieavbrott.','procent','UKÄ','77','Årlig','publik',false),
('uka-prestationsgrad','Prestationsgrad','Individkopplade avklarade poäng under registreringsterminen och tre efterföljande terminer dividerat med registreringspoäng. Period = registreringsläsår. Kön, lärosäte, program/kurs och campus/distans där källan redovisar dem. UF0208, SCB:s reviderade tabell 4; inte kvoten av fristående HPR/HST-uttag.','procent','UKÄ','UF0208 tabell 4','Årlig','publik',false),
('uka-regional-examinerade','Examinerade i regional uppföljning','Publicerad nämnare i UF0205:s regionala tabell (tabell 34 i SM 2026:1). Period = examensläsår, uppföljningsdatum i dimension. Endast lärosäten som källan redovisar, minst 500 examinerade; SLU saknas. Källans antal kan vara avrundade. Nämnaren ska inte ersättas med indikator 108.','antal','UKÄ','UF0205 regional tabell','Årlig','publik',false),
('uka-regional-rekryterade-antal','Examinerade rekryterade från högskolelänet','Publicerat antal bland samma examensårskull som den regionala uppföljningen. Rekryteringslän = folkbokföringslän året före högskolestart. Ingen beräkning från procent. Könsuppdelning saknas. Högskolelän enligt källan, inte studieort eller arbetsplats.','antal','UKÄ','UF0205 regional tabell','Årlig','publik',false),
('uka-regional-bosatta-antal','Examinerade bosatta i högskolelänet','Publicerat antal bosatta i högskolelänet omkring två år efter examen. Period = examensläsår, exakt uppföljningsdatum i dimension. Könsuppdelning saknas. Avser bosättning, inte arbetsplats. Ingen beräkning från procent.','antal','UKÄ','UF0205 regional tabell','Årlig','publik',false),
('uka-regional-rekryterade-andel','Examinerade rekryterade från högskolelänet, andel','Publicerad avrundad andel av den regionala examensårskullen som rekryterades från högskolelänet. Period = examensläsår. Könsuppdelning saknas. Motstridiga källuppgifter spärras.','procent','UKÄ','UF0205 regional tabell','Årlig','publik',false),
('uka-regional-bosatta-andel','Examinerade bosatta i högskolelänet, andel','Publicerad avrundad andel bosatta i högskolelänet vid angivet uppföljningsdatum omkring två år efter examen. Period = examensläsår. Könsuppdelning saknas. Avser bosättning, inte arbetsplats.','procent','UKÄ','UF0205 regional tabell','Årlig','publik',false)
