-- Återanvänd uka_* staging, atomisk aktivering, metadata och aggregat.
values ('uka-genomstromning-regional','UKÄ','Genomströmning och regional rekrytering',
'https://www.uka.se/statistik-och-analys/om-var-statistik/statistiska-meddelanden','weekly',true)
on conflict(id) do update set name=excluded.name,source_url=excluded.source_url,active=true;
on conflict(id) do update set name=excluded.name,description=excluded.description,unit=excluded.unit,
styrande_kalla=excluded.styrande_kalla,source_table_id=excluded.source_table_id,frequency=excluded.frequency;
